messageValues.message:
You are an accounting data-extraction engine. Return ONLY one JSON object, no markdown fences, with exactly these keys:
{"vendor": string, "invoice_number": string|null, "invoice_date": "YYYY-MM-DD"|null, "document_type": "invoice"|"receipt"|"order"|"other", "currency": string|null, "net_amount": number|null, "tax_amount": number|null, "total_amount": number|null, "confidence": number}

Rules: parse numbers as plain numbers without thousands separators; confidence is 0 to 1 and reflects how sure you are the fields are right; if the document is clearly not an invoice, receipt or order confirmation, return {"vendor": null, "confidence": 0}.

parameters.jsCode:
let s = String($input.first().json.text ?? '').trim();
s = s.replace(/^```(?:json)?/i, '').replace(/```\s*$/, '').trim();
const start = s.indexOf('{');
const end = s.lastIndexOf('}');
if (start === -1 || end === -1) {
  throw new Error('The AI did not return a JSON object.');
}
const inv = JSON.parse(s.slice(start, end + 1));

const reasons = [];
if (!inv.vendor) reasons.push('the AI does not think this is an invoice or receipt');
if (typeof inv.confidence === 'number' && inv.confidence < 0.7) {
  reasons.push('extraction confidence is only ' + inv.confidence);
}
const net = inv.net_amount, tax = inv.tax_amount, total = inv.total_amount;
if ([net, tax, total].every((v) => typeof v === 'number') && Math.abs(net + tax - total) > 0.02) {
  reasons.push('net + tax does not match the total (' + net + ' + ' + tax + ' vs ' + total + ')');
}
if (total == null) reasons.push('no total amount found');
if (inv.currency) inv.currency = String(inv.currency).toUpperCase();

return [{ json: {
  ...inv,
  vendor: inv.vendor ?? '(not detected)',
  needs_review: reasons.length > 0,
  review_reason: reasons.join('; '),
} }];

const inv = $('Validate AI Invoice Data').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r.row_number !== undefined);
const duplicate = Boolean(inv.invoice_number) && rows.length > 0;
return [{ json: { ...inv, duplicate } }];

